<?php
namespace App\Http\Controllers;
use App\Models\Content; use App\Models\Setting; use Inertia\Inertia; use Inertia\Response;
class PublicController extends Controller { private function data():array{return ['settings'=>Setting::values(),'services'=>Content::published()->where('type','service')->orderBy('sort_order')->get(),'solutions'=>Content::published()->where('type','solution')->orderBy('sort_order')->get(),'industries'=>Content::published()->where('type','industry')->orderBy('sort_order')->get(),'projects'=>Content::published()->where('type','project')->latest('published_at')->take(3)->get(),'testimonials'=>Content::published()->where('type','testimonial')->get(),'faqs'=>Content::published()->where('type','faq')->orderBy('sort_order')->get(),'partners'=>Content::published()->where('type','partner')->orderBy('sort_order')->get()];} public function home():Response{return Inertia::render('Public/Home',$this->data());} public function page(string $slug):Response{$page=Content::published()->where('type','page')->where('slug',$slug)->firstOrFail();return Inertia::render('Public/Page',['page'=>$page,...$this->data()]);} public function listing(string $type):Response{abort_unless(in_array($type,['services','solutions','industries','projects']),404);$singular=['services'=>'service','solutions'=>'solution','industries'=>'industry','projects'=>'project'][$type];return Inertia::render('Public/Listing',['title'=>ucfirst($type),'items'=>Content::published()->where('type',$singular)->orderBy('sort_order')->paginate(12),'type'=>$type,...$this->data()]);} public function detail(string $type,string $slug):Response{abort_unless(in_array($type,['services','solutions','industries','projects']),404);$item=Content::published()->where('type',['services'=>'service','solutions'=>'solution','industries'=>'industry','projects'=>'project'][$type])->where('slug',$slug)->firstOrFail();return Inertia::render('Public/Detail',['item'=>$item,'type'=>$type,'faqs'=>Content::published()->where('type','faq')->orderBy('sort_order')->get(),...$this->data()]);} public function contact():Response{return Inertia::render('Public/Contact',$this->data());} }
